#include <iostream>
using namespace std;

int main() {
    int choice;

    do {
        cout << "--- Menu ---" << endl;
        cout << "1. Say hello" << endl;
        cout << "2. Add two numbers" << endl;
        cout << "0. Quit" << endl;
        cout << "Choice? ";
        cin >> choice;

        if (choice == 1) {
            cout << "Hello!" << endl;
        } else if (choice == 2) {
            cout << "First? ";
            int a;
            cin >> a;
            cout << "Second? ";
            int b;
            cin >> b;
            cout << "Sum: " << a + b << endl;
        } else if (choice != 0) {
            cout << "I do not know option " << choice << "." << endl;
        }
    } while (choice != 0);

    cout << "Goodbye." << endl;
    return 0;
}

