#include <iostream>
using namespace std;

int main() {
    int choice;

    do {
        cout << "1. Say hello" << endl;
        cout << "2. Count to three" << endl;
        cout << "0. Quit" << endl;
        cout << "Choice? ";
        cin >> choice;

        if (choice == 1) {
            cout << "Hello!" << endl;
        } else if (choice == 2) {
            for (int i = 1; i <= 3; i++) {
                cout << i << endl;
            }
        } else if (choice != 0) {
            cout << "No such option." << endl;
        }
    } while (choice != 0);

    cout << "Goodbye." << endl;

    return 0;
}

